#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

// Feel free to change the data structures generated by AI.
extern char **environ;

// 最多统计 1024 个系统调用
#define MAX_SYSCALLS 1024
// 每次最多返回 TOP 5 时长的系统调用
#define TOP_N 5
// 连续观测到系统调用时，每 100ms 打印一次统计结果
#define PRINT_CYCLE 100
// 可接受的最长参数长度（不要命名为 PATH_MAX：<limits.h> 已有同名宏）
#define MAX_PATH_LEN 1024

// 每次系统调用的统计信息
typedef struct {
    char   name[64]; // 系统调用名称，来自 strace 输出
    double time;     // 系统调用的执行时间，单位为秒
} syscall_stat;

// 一次统计的系统调用信息
typedef struct {
    syscall_stat stats[MAX_SYSCALLS];
    int          count;      // 当前统计的系统调用数量
    double       total_time; // 当前统计的系统调用总时间
} syscall_stats;

/**
 * @brief 解析一行 strace 输出，提取系统调用名称和执行时间
 *
 * @param line strace 原始一行输出
 * @param syscall_name 提取的系统调用名称
 * @param time 提取的系统调用执行时间
 * @return int 解析成功返回 0，失败返回 -1
 */
int parse_strace_line(char *line, char *syscall_name, double *time) {
    // strace 输出格式示例：
    // openat(AT_FDCWD, "/etc/ld.so.cache", O_RDONLY|O_CLOEXEC) = 3 <0.000123>
    // 解析系统调用名称和执行时间
    // 找到第一个 '(' 截取系统调用名称
    // 找到最后一个 '<' 截取执行时间
    // 跳过 [pid xxx] 前缀
    char *pid_prefix = strstr(line, "] ");
    if (pid_prefix) {
        line = pid_prefix + 2; // 跳过 "] "
    }
    // 行末必须紧邻 '>'（形如 ... <0.000123>），否则可能是被追踪程序
    // 自己打印出来的 "<99999.9>"，不能当成合法的时间后缀
    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r' || line[len - 1] == ' ' ||
                       line[len - 1] == '\t')) {
        line[--len] = '\0';
    }
    if (len == 0 || line[len - 1] != '>') {
        return -1; // 行末不是 '>'，不是一条合法的 trace 行
    }
    char *paren = strchr(line, '(');
    if (!paren) {
        return -1; // 没有找到 '('，解析失败
    }
    size_t name_len = paren - line;
    if (name_len >= 64) {
        name_len = 63; // 防止溢出
    }
    strncpy(syscall_name, line, name_len);
    syscall_name[name_len] = '\0'; // 确保字符串以 NULL 结尾
    // 从后面找到最后一个 '<'，然后提取执行时间
    char *lt = strrchr(line, '<');
    if (!lt) {
        return -1; // 没有找到 '<'，解析失败
    }
    // 提取执行时间，格式为 <0.000123>
    // 用 strtod 保证解析成功
    char  *endptr;
    double t = strtod(lt + 1, &endptr);
    // 必须解析到数字，且恰好停在行末那个 '>' 上
    if (endptr == lt + 1 || *endptr != '>' || endptr != line + len - 1) {
        return -1; // 没解析到数字，或 '<...>' 不在行末，解析失败
    }
    *time = t;
    return 0; // 解析成功
}

/**
 * @brief 给定的系统调用统计结构体中添加一个系统调用的执行时间
 *
 * @param stats 目标统计结构体
 * @param name 目标系统调用名称
 * @param time 目标系统调用执行时间
 */
void add_syscall(syscall_stats *stats, const char *name, double time) {
    // 查找是否已经存在该系统调用
    for (int i = 0; i < stats->count; i++) {
        if (strcmp(stats->stats[i].name, name) == 0) {
            // 如果存在，则累加时间
            stats->stats[i].time += time;
            stats->total_time += time;
            return;
        }
    }
    // 找不到，则添加新的系统调用
    if (stats->count < MAX_SYSCALLS) {
        strncpy(stats->stats[stats->count].name, name, sizeof(stats->stats[stats->count].name) - 1);
        stats->stats[stats->count].name[sizeof(stats->stats[stats->count].name) - 1] =
            '\0'; // 确保字符串以 NULL 结尾
        stats->stats[stats->count].time = time;
        stats->count++;
        stats->total_time += time;
    } else {
        fprintf(stderr, "Warning: Maximum number of syscalls reached, ignoring %s\n", name);
    }
}

// ---------------------------------------------------------------------------
// 历史趋势 (sparkline)
//
// 关键点：stats->stats[] 必须始终保持“插入顺序”不变，下标才能当作稳定的 id
// 去索引历史。所以下面排序的是“索引数组”而不是 stats 本身。
// ---------------------------------------------------------------------------

#define SPARK_LEN 32 // 保留最近多少轮采样
#define SPARK_W   24 // 屏幕上显示多少个字符（<= SPARK_LEN）

typedef struct {
    double ratio[SPARK_LEN]; // 环形缓冲
    int    cnt;              // 已记录轮数（<= SPARK_LEN）
    int    pos;              // 下一个写入位置
} spark_hist;

static spark_hist g_spark[MAX_SYSCALLS];

// 上一轮打印时的累计耗时，用来算“本区间”的增量
static double g_prev_time[MAX_SYSCALLS];
static double g_prev_total;

// qsort 的比较函数拿不到上下文，用全局基址传 stats 数组
static const syscall_stat *g_sort_base;

static int cmp_index_by_time(const void *pa, const void *pb) {
    int    ia = *(const int *)pa;
    int    ib = *(const int *)pb;
    double ta = g_sort_base[ia].time;
    double tb = g_sort_base[ib].time;
    if (ta < tb) {
        return 1; // 时间大的排前面
    }
    if (ta > tb) {
        return -1;
    }
    return 0;
}

static void spark_push(int id, double ratio) {
    if (id < 0 || id >= MAX_SYSCALLS) {
        return;
    }
    spark_hist *s    = &g_spark[id];
    s->ratio[s->pos] = ratio;
    s->pos           = (s->pos + 1) % SPARK_LEN;
    if (s->cnt < SPARK_LEN) {
        s->cnt++;
    }
}

// 用 ▁▂▃▄▅▆▇█ 把最近若干轮的占比画成一段趋势
static void spark_render(int id) {
    if (id < 0 || id >= MAX_SYSCALLS) {
        return;
    }
    static const char *const blocks[] = {"▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"};
    const spark_hist        *s        = &g_spark[id];

    int show = s->cnt < SPARK_W ? s->cnt : SPARK_W;
    for (int k = 0; k < show; k++) {
        // 环形缓冲里最旧的一条起点
        int idx = (s->pos + SPARK_LEN - show + k) % SPARK_LEN;
        int lv  = (int)(s->ratio[idx] * 7.0 + 0.5);
        if (lv < 0) {
            lv = 0;
        }
        if (lv > 7) {
            lv = 7;
        }
        fputs(blocks[lv], stdout);
    }
}

/**
 * @brief 终端宽度；不是终端或取不到时退回 80
 */
static int term_width(void) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
        return ws.ws_col;
    }
    return 80;
}

/**
 * @brief 在终端里画横向条形图（只在 isatty 时调用）
 *
 * 用 ANSI 背景色填充空格，条长与耗时占比成正比。
 * 末尾额外画一段 (other)，把未进入 top n 的系统调用也计入，
 * 这样全部条的长度加起来正好铺满整行，视觉上就是“ 100%”。
 */
static void print_bar_chart(const syscall_stats *stats, const int *idx, int n) {
    // 2(缩进) + 15(名字) + 1(空格) + width(条) + 6(" 99% ") + SPARK_W(趋势)
    int width = term_width() - 24 - SPARK_W;
    if (width < 8) {
        width = 8;
    }
    if (width > 40) {
        width = 40;
    }

    double shown = 0.0;
    for (int k = 0; k < n && k < stats->count; k++) {
        int    i     = idx[k];
        double ratio = stats->stats[i].time / stats->total_time;
        shown += ratio;

        int fill = (int)(ratio * width + 0.5); // 四舍五入到整格
        if (fill < 1 && ratio > 0.0) {
            fill = 1; // 非零占比至少可见 1 格
        }

        printf("  %-15s ", stats->stats[i].name);
        printf("\033[%dm", 41 + k % 5); // 41..45：红/绿/黄/蓝/紫背景
        for (int b = 0; b < fill; b++) {
            putchar(' ');
        }
        printf("\033[0m");
        for (int b = fill; b < width; b++) {
            putchar(' '); // 剩余部分用普通空格占位，保证百分比列对齐
        }
        printf(" %3d%% ", (int)(ratio * 100));
        spark_render(i); // 该 syscall 最近若干轮的占比趋势
        printf("\n");
    }

    // 未进入 top n 的部分
    if (shown < 0.999) {
        int fill = (int)((1.0 - shown) * width + 0.5);
        printf("  %-15s ", "(other)");
        printf("\033[47m"); // 浅灰背景
        for (int b = 0; b < fill; b++) {
            putchar(' ');
        }
        printf("\033[0m");
        for (int b = fill; b < width; b++) {
            putchar(' ');
        }
        printf(" %3d%%\n", (int)((1.0 - shown) * 100));
    }
}

void print_top_syscalls(syscall_stats *stats, int n) {
    // 没有数据或总时间为 0 时本轮不输出任何内容：既避免除零，
    // 也避免向 OJ 的 stdout 写入格式之外的行
    if (stats->count == 0 || stats->total_time <= 0.0) {
        return;
    }

    // 排序的是索引数组，stats->stats[] 的插入顺序保持不变，
    // 下标于是可以直接当作 sparkline 历史的稳定 id
    int idx[MAX_SYSCALLS];
    for (int i = 0; i < stats->count; i++) {
        idx[i] = i;
    }
    g_sort_base = stats->stats;
    qsort(idx, stats->count, sizeof(int), cmp_index_by_time);

    // 终端：清屏 + 条形图 + 趋势；OJ 重定向时：完全符合 spec 的裸文本
    if (isatty(STDOUT_FILENO)) {
        // 记录“本区间”的占比而不是累计占比：用与上一轮打印时的差值，
        // 这样 sparkline 反映的是最近 ~100ms 的活跃度变化，
        // 而不是越来越平的累计曲线
        double total_delta = stats->total_time - g_prev_total;
        if (total_delta > 0.0) {
            for (int i = 0; i < stats->count; i++) {
                double delta = stats->stats[i].time - g_prev_time[i];
                spark_push(i, delta > 0.0 ? delta / total_delta : 0.0);
                g_prev_time[i] = stats->stats[i].time;
            }
            g_prev_total = stats->total_time;
        }

        printf("\033[2J\033[H"); // 清屏 + 光标归位
        printf("sperf: top %d  total %.6fs  (%d syscalls)\n\n", n, stats->total_time, stats->count);
        print_bar_chart(stats, idx, n);
        printf("\n");
    } else {
        // 只打印前 n 个系统调用的耗时占比，每个系统调用每轮至多出现一次
        for (int k = 0; k < n && k < stats->count; k++) {
            int i = idx[k];
            printf("%s (%d%%)\n", stats->stats[i].name,
                   (int)(stats->stats[i].time * 100 / stats->total_time));
        }
    }

    // 80 个 '\0'（数值 0，不是字符 '0'）作为本轮输出的分块标记
    for (int i = 0; i < 80; i++) {
        putchar('\0');
    }
    // OJ 下 stdout 是 fully buffered，必须显式 flush 才能被观测到
    fflush(stdout);
}

static double now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}

// 把 buf 中所有以 '\n' 结尾的完整行解析掉，残留半行挪到缓冲区开头。
// 返回：本批是否新增/更新过统计（供 dirty 标志使用）
static bool consume_lines(char *buf, size_t *len, syscall_stats *stats) {
    bool   got   = false;
    size_t start = 0;

    for (size_t k = 0; k < *len; k++) {
        if (buf[k] == '\n') {
            buf[k] = '\0';
            char   name[64];
            double t;
            if (parse_strace_line(buf + start, name, &t) == 0) {
                add_syscall(stats, name, t);
                got = true;
            }
            start = k + 1;
        }
    }
    if (start > 0) {
        memmove(buf, buf + start, *len - start);
        *len -= start;
    }
    return got;
}

/**
 * @brief 在 PATH 中查找命令，等价于 execvp 的“搜索”阶段
 *
 * 自身只调用 access() 预检查，不执行任何程序；真正的执行仍由调用方
 * 用 execve() 完成（题目只允许 execve）。
 *
 * @param name   命令名（不含 '/'）
 * @param out    找到时写入完整路径
 * @param outlen out 的容量
 * @return char* 找到返回 out，找不到或 PATH 不可用返回 NULL
 */
static char *find_in_path(const char *name, char *out, size_t outlen) {
    const char *path_env = getenv("PATH");
    if (path_env == NULL) {
        return NULL;
    }

    char *paths = strdup(path_env); // 复制一份，不要污染真正的 PATH
    if (paths == NULL) {
        return NULL;
    }

    char *found = NULL;
    char *save  = NULL;
    for (char *dir = strtok_r(paths, ":", &save); dir; dir = strtok_r(NULL, ":", &save)) {
        // PATH 中的空目录项按 POSIX 语义视为当前目录
        const char *d = (dir[0] == '\0') ? "." : dir;
        int         n = snprintf(out, outlen, "%s/%s", d, name);
        if (n > 0 && (size_t)n < outlen && access(out, X_OK) == 0) {
            found = out;
            break;
        }
    }

    free(paths);
    return found;
}

int main(int argc, char *argv[]) {
    // 检查命令行参数
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <command> [args...]\n", argv[0]);
        return 1;
    }
    // 命令名含 '/' 时按路径直接执行，否则在 PATH 中查找。
    // 找不到就在 fork 之前报错，不要把这个错误留给 strace 去打印。
    static char full_path[MAX_PATH_LEN];
    char       *command_path = argv[1];

    if (strchr(command_path, '/') == NULL) {
        char *resolved = find_in_path(command_path, full_path, sizeof(full_path));
        if (resolved == NULL) {
            fprintf(stderr, "%s: command not found\n", command_path);
            return 127;
        }
        command_path = resolved;
    }

    // strace 自身也用同样的方式搜索，再退回常见安装位置
    static char strace_path[MAX_PATH_LEN];
    char       *strace_bin = find_in_path("strace", strace_path, sizeof(strace_path));
    if (strace_bin == NULL) {
        static const char *const fallbacks[] = {"/bin/strace", "/usr/bin/strace"};
        for (size_t k = 0; k < sizeof(fallbacks) / sizeof(fallbacks[0]); k++) {
            if (access(fallbacks[k], X_OK) == 0) {
                snprintf(strace_path, sizeof(strace_path), "%s", fallbacks[k]);
                strace_bin = strace_path;
                break;
            }
        }
    }
    if (strace_bin == NULL) {
        fprintf(stderr, "sperf: strace not found\n");
        return 127;
    }

    // 初始化统计结构体
    syscall_stats stats = {0};
    // 使用管道和子进程通信
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    } // 创建管道后，父进程将读取 strace 输出，子进程将 strace 输出写入管道
    // pipefd[0] 是父进程读取端，pipefd[1] 是子进程写入端
    // 单向通信

    // 准备 strace 命令参数
    // 1. strace
    // 2. -T 参数，表示输出每个系统调用的执行时间
    // 3. -o 重定向到管道，与父进程通信
    // 4. command_path，表示要执行的命令
    // strace -T -o /dev/fd/3 command_path [args...] NULL
    size_t args      = (size_t)(argc - 2);
    size_t total     = 4 + 1 + args + 1;
    char **exec_args = calloc(total, sizeof(char *));
    if (exec_args == NULL) {
        perror("calloc");
        return 1;
    }
    size_t i       = 0;
    exec_args[i++] = "strace";
    exec_args[i++] = "-T";
    exec_args[i++] = "-o";
    exec_args[i++] = "/dev/fd/3";  // 将 strace 输出
    exec_args[i++] = command_path; // 要执行的命令
    // 注意这里是 argc 而不是 args：args 是用户参数个数，不是结束下标
    for (int k = 2; k < argc; k++) {
        exec_args[i++] = argv[k];
    }
    exec_args[i] = NULL; // 必须以 NULL 结尾

    // fork 一个子进程来执行 strace
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        // 进入子进程，执行 strace 命令
        // 从父进程继承，需要关闭管道的读取端
        close(pipefd[0]);
        // dup2 将管道写入端重定向到 fd 3，这样 strace 的输出就会写入管道
        if (dup2(pipefd[1], 3) < 0) {
            perror("dup2");
            _exit(1);
        }
        // 检查 pipefd[1] 是否为 3，如果不是，则关闭 pipefd[1]
        if (pipefd[1] != 3) {
            close(pipefd[1]);
        }
        // 静音被追踪程序的输出：fd 1 总是接到 /dev/null，因为统计结果也占用
        // stdout，两者混在一起没法看。strace 自己的 trace 走 fd 3
        // （-o /dev/fd/3），完全不受影响。
        //
        // stderr 只在真正的终端上静音：find / 这类命令会打出几千行
        // “Permission denied”，每 100ms 的清屏重绘之间夹几条错误信息，
        // 统计表就没法看了。重定向到文件/管道时保留 stderr，既方便排查
        // 问题，也不影响 “stderr 不污染 trace” 的验证。
        int devnull = open("/dev/null", O_WRONLY);
        if (devnull < 0) {
            perror("open /dev/null");
            _exit(1);
        }
        if (dup2(devnull, STDOUT_FILENO) < 0) {
            perror("dup2 /dev/null -> stdout");
            _exit(1);
        }
        // 注意：上面换掉的是 fd 1，不影响 fd 2 的 isatty 结果
        if (isatty(STDERR_FILENO)) {
            if (dup2(devnull, STDERR_FILENO) < 0) {
                perror("dup2 /dev/null -> stderr");
                _exit(1);
            }
        }
        // devnull 可能正好是 1 或 2（stdin/stdout/stderr 被关闭时），别误关
        if (devnull != STDOUT_FILENO && devnull != STDERR_FILENO) {
            close(devnull);
        }
        // 使用 execve 命令，将 strace 的输出重定向到管道中
        execve(strace_bin, exec_args, environ);
        // execve 失败，打印错误信息并退出
        perror("execve");
        _exit(127);
    }
    // 父进程关闭写端，否则会导致管道无法读取到 EOF
    close(pipefd[1]);

    // 统计和打印系统调用信息
    char  *buf = NULL; // 手动管理行缓冲
    size_t len = 0;    // 已缓冲的字节数
    size_t cap = 0;    // 缓冲区容量

    double last_print = now_ms();
    bool   dirty      = false; // 是否有新的系统调用统计信息
    bool   eof        = false; // 是否已经读到管道 EOF

    while (!eof) {
        struct pollfd pfd   = {.fd = pipefd[0], .events = POLLIN};
        int           ready = poll(&pfd, 1, PRINT_CYCLE);
        if (ready < 0) {
            if (errno == EINTR) {
                continue; // 被信号中断，继续等待
            }
            perror("poll");
            break;
        }

        // 判断接收到的数据是否可读
        if (ready > 0 && (pfd.revents & (POLLIN | POLLHUP))) {
            if (cap - len < 4096) {
                size_t new_cap = cap == 0 ? 65536 : cap * 2;
                char  *new_buf = realloc(buf, new_cap);
                if (!new_buf) {
                    perror("realloc");
                    break;
                }
                buf = new_buf;
                cap = new_cap;
            }
            ssize_t n = read(pipefd[0], buf + len, cap - len);
            if (n > 0) {
                len += (size_t)n;
                if (consume_lines(buf, &len, &stats)) {
                    dirty = true;
                }
            } else if (n == 0) {
                eof = true; // 管道 EOF
            } else if (errno != EINTR) {
                perror("read");
                break;
            }
        }
        // 每 PRINT_CYCLE 毫秒打印一次统计信息
        double now = now_ms();
        if (dirty && now - last_print >= PRINT_CYCLE) {
            print_top_syscalls(&stats, TOP_N);
            last_print = now;
            dirty      = false;
        }
    }
    close(pipefd[0]); // 关闭读取端，表示父进程不再读取 strace 输出
    free(buf);        // 释放缓冲区

    // 管道 EOF，子进程即将/已经结束
    int status;
    waitpid(pid, &status, 0);
    // 打印最后一轮统计（短程序只走到这里，保证至少有一轮输出）
    print_top_syscalls(&stats, TOP_N);
    free(exec_args);

    // 把子进程（strace / 被追踪程序）的退出状态透传给调用者，
    // 否则 `sperf not-a-command` 会以 0 退出，看起来像成功了
    if (WIFEXITED(status)) {
        return WEXITSTATUS(status);
    }
    if (WIFSIGNALED(status)) {
        return 128 + WTERMSIG(status);
    }
    return 0;
}